enum VoteType {
    UPVOTE,   // increases score and author reputation
    DOWNVOTE  // decreases score and author reputation, costs the voter reputation too
}

// A member of the site with an earned reputation score.
class User {
    private final String userId;  // unique id
    private final String name;    // display name
    private int reputation;        // earned standing, gates certain actions

    public User(String userId, String name, int reputation) {
        this.userId = userId;      // store id
        this.name = name;           // store name
        this.reputation = reputation; // store starting reputation
    }

    public String getUserId() { return userId; }         // id getter
    public String getName() { return name; }               // name getter
    public int getReputation() { return reputation; }        // reputation getter
    public void addReputation(int amount) { reputation += amount; } // adjust reputation up or down
}

// A question posted by a user.
class Question {
    private final String questionId; // unique id, e.g. Q1
    private final String authorId;    // who asked it
    private final String title;        // question title
    private int score;                  // net upvotes minus downvotes
    private String acceptedAnswerId;     // null until an answer is accepted

    public Question(String questionId, String authorId, String title) {
        this.questionId = questionId; // store id
        this.authorId = authorId;      // store author
        this.title = title;             // store title
        this.score = 0;                  // starts at zero
        this.acceptedAnswerId = null;     // no accepted answer yet
    }

    public String getQuestionId() { return questionId; }      // id getter
    public String getAuthorId() { return authorId; }            // author getter
    public int getScore() { return score; }                      // score getter
    public void adjustScore(int delta) { score += delta; }         // apply a vote's effect
    public String getAcceptedAnswerId() { return acceptedAnswerId; } // accepted getter
    public void setAcceptedAnswerId(String answerId) { this.acceptedAnswerId = answerId; } // accepted setter
}

// An answer posted to a question.
class Answer {
    private final String answerId;    // unique id, e.g. A1
    private final String questionId;   // which question this answers
    private final String authorId;      // who answered
    private int score;                   // net upvotes minus downvotes
    private boolean isAccepted;           // whether this is the accepted answer

    public Answer(String answerId, String questionId, String authorId) {
        this.answerId = answerId;    // store id
        this.questionId = questionId; // store question reference
        this.authorId = authorId;      // store author
        this.score = 0;                 // starts at zero
        this.isAccepted = false;         // not accepted yet
    }

    public String getAnswerId() { return answerId; }       // id getter
    public String getQuestionId() { return questionId; }     // question getter
    public String getAuthorId() { return authorId; }          // author getter
    public int getScore() { return score; }                     // score getter
    public void adjustScore(int delta) { score += delta; }        // apply a vote's effect
    public boolean isAccepted() { return isAccepted; }             // accepted getter
    public void setAccepted(boolean accepted) { this.isAccepted = accepted; } // accepted setter
}

// Records that a specific user has already voted on a specific post.
class VoteRecord {
    private final String voterId;  // who voted
    private final String postId;    // which question or answer
    private final VoteType voteType; // up or down

    public VoteRecord(String voterId, String postId, VoteType voteType) {
        this.voterId = voterId;   // store voter
        this.postId = postId;      // store post
        this.voteType = voteType;   // store vote type
    }

    public String getVoterId() { return voterId; }  // voter getter
    public String getPostId() { return postId; }      // post getter
}

// Creates sequential, correctly-prefixed ids for questions and answers.
class PostIdFactory {
    private int questionCounter = 0; // running id counter for questions
    private int answerCounter = 0;    // running id counter for answers

    public String nextQuestionId() {
        questionCounter++;                  // bump id counter
        return "Q" + questionCounter;        // e.g. Q1
    }

    public String nextAnswerId() {
        answerCounter++;                    // bump id counter
        return "A" + answerCounter;          // e.g. A1
    }
}

