// Strategy interface: how many reputation points an action is worth.
interface ReputationStrategy {
    int pointsForVote(String postType, VoteType voteType); // points for the post's author
    int downvoteVoterCost();                                 // reputation cost to the person casting a downvote
    int minimumReputationToDownvote();                        // threshold required to downvote at all
    int pointsForAcceptedAnswerAuthor();                        // bonus for the answer that gets accepted
    int pointsForAcceptingAsker();                               // bonus for the question author who accepts
}

// The standard, well-known point scheme this design is modeled on.
class StandardReputationStrategy implements ReputationStrategy {
    @Override
    public int pointsForVote(String postType, VoteType voteType) {
        if (voteType == VoteType.DOWNVOTE) return -2; // downvote always costs the author 2, regardless of post type
        return postType.equals("QUESTION") ? 5 : 10;   // upvote: question author gets 5, answer author gets 10
    }

    @Override
    public int downvoteVoterCost() { return -1; } // casting a downvote costs the voter 1 reputation

    @Override
    public int minimumReputationToDownvote() { return 125; } // must have earned at least this much to downvote

    @Override
    public int pointsForAcceptedAnswerAuthor() { return 15; } // bonus for having your answer accepted

    @Override
    public int pointsForAcceptingAsker() { return 2; } // small bonus for the asker who accepts an answer
}

// Observer interface: reacts to voting and acceptance lifecycle events.
interface QAObserver {
    void onVoteCast(String postId, String voterId, VoteType voteType);          // vote applied successfully
    void onVoteRejected(String voterId, String postId, String reason);           // vote blocked
    void onAnswerAccepted(String answerId, String questionId);                    // answer marked accepted
}

// Simple observer that prints events to the console.
class ConsoleQAObserver implements QAObserver {
    @Override
    public void onVoteCast(String postId, String voterId, VoteType voteType) {
        System.out.println(voterId + " cast a " + voteType + " on " + postId);
    }

    @Override
    public void onVoteRejected(String voterId, String postId, String reason) {
        System.out.println("Vote rejected for " + voterId + " on " + postId + ": " + reason);
    }

    @Override
    public void onAnswerAccepted(String answerId, String questionId) {
        System.out.println("Answer " + answerId + " accepted for question " + questionId);
    }
}

