// Custom exceptions for the realistic failure modes.
class VotingNotAllowedException extends RuntimeException {
    public VotingNotAllowedException(String msg) { super(msg); }
}
class UnauthorizedAcceptException extends RuntimeException {
    public UnauthorizedAcceptException(String msg) { super(msg); }
}
class InvalidPostException extends RuntimeException {
    public InvalidPostException(String msg) { super(msg); }
}

// The core orchestrator tying every piece together.
class QAService {
    private final java.util.Map<String, User> users = new java.util.HashMap<>();           // userId -> User
    private final java.util.Map<String, Question> questions = new java.util.HashMap<>();    // questionId -> Question
    private final java.util.Map<String, Answer> answers = new java.util.HashMap<>();        // answerId -> Answer
    private final java.util.Set<String> voteKeys = new java.util.HashSet<>();                 // voterId plus postId, for duplicate checks
    private final ReputationStrategy reputationStrategy; // pluggable point scheme
    private final java.util.List<QAObserver> observers = new java.util.ArrayList<>(); // listeners

    public QAService(ReputationStrategy reputationStrategy) {
        this.reputationStrategy = reputationStrategy; // store chosen scheme
    }

    public void addUser(User user) { users.put(user.getUserId(), user); }             // register a user
    public void addQuestion(Question question) { questions.put(question.getQuestionId(), question); } // register a question
    public void addAnswer(Answer answer) { answers.put(answer.getAnswerId(), answer); } // register an answer
    public void addObserver(QAObserver observer) { observers.add(observer); }            // register a listener

    private String authorOf(String postId) {
        if (questions.containsKey(postId)) return questions.get(postId).getAuthorId(); // question author
        return answers.get(postId).getAuthorId();                                       // answer author
    }

    private String typeOf(String postId) {
        return questions.containsKey(postId) ? "QUESTION" : "ANSWER"; // distinguish post type for point calculation
    }

    // Casts a vote, applying score and reputation changes, or rejecting it with a clear reason.
    public synchronized void castVote(String voterId, String postId, VoteType voteType) {
        String authorId = authorOf(postId); // who owns this post
        if (authorId.equals(voterId)) {                                        // self-vote check
            for (QAObserver obs : observers) obs.onVoteRejected(voterId, postId, "Cannot vote on your own post"); // notify
            throw new VotingNotAllowedException("Cannot vote on your own post");
        }
        String voteKey = voterId + "|" + postId;                                // unique key for this voter and post
        if (voteKeys.contains(voteKey)) {                                        // duplicate-vote check
            for (QAObserver obs : observers) obs.onVoteRejected(voterId, postId, "Already voted on this post"); // notify
            throw new VotingNotAllowedException("Already voted on this post");
        }
        User voter = users.get(voterId);                                          // look up voter
        if (voteType == VoteType.DOWNVOTE && voter.getReputation() < reputationStrategy.minimumReputationToDownvote()) {
            for (QAObserver obs : observers) obs.onVoteRejected(voterId, postId, "Insufficient reputation to downvote"); // notify
            throw new VotingNotAllowedException("Insufficient reputation to downvote");
        }
        String postType = typeOf(postId);                                          // question or answer
        int authorPoints = reputationStrategy.pointsForVote(postType, voteType);     // points for the author
        users.get(authorId).addReputation(authorPoints);                              // apply to author
        if (voteType == VoteType.DOWNVOTE) {                                           // downvote costs the voter too
            voter.addReputation(reputationStrategy.downvoteVoterCost());
        }
        int scoreDelta = voteType == VoteType.UPVOTE ? 1 : -1;                           // score always moves by 1
        if (questions.containsKey(postId)) questions.get(postId).adjustScore(scoreDelta); // adjust question score
        else answers.get(postId).adjustScore(scoreDelta);                                  // adjust answer score
        voteKeys.add(voteKey);                                                              // record this vote
        for (QAObserver obs : observers) obs.onVoteCast(postId, voterId, voteType);         // notify
    }

    // Marks an answer accepted, granting the dual reputation bonus, if the caller is the question's author.
    public synchronized void acceptAnswer(String callerId, String questionId, String answerId) {
        Question question = questions.get(questionId);                    // look up question
        if (question == null) throw new InvalidPostException("Unknown question: " + questionId);
        if (!question.getAuthorId().equals(callerId)) {                     // must be the question's own author
            throw new UnauthorizedAcceptException("Only the question author can accept an answer");
        }
        Answer answer = answers.get(answerId);                              // look up answer
        if (answer == null) throw new InvalidPostException("Unknown answer: " + answerId);
        answer.setAccepted(true);                                             // mark accepted
        question.setAcceptedAnswerId(answerId);                                // record on the question
        users.get(answer.getAuthorId()).addReputation(reputationStrategy.pointsForAcceptedAnswerAuthor()); // answerer bonus
        users.get(callerId).addReputation(reputationStrategy.pointsForAcceptingAsker());                     // asker bonus
        for (QAObserver obs : observers) obs.onAnswerAccepted(answerId, questionId);                           // notify
    }
}

