#include <string>
#include <vector>
#include <map>
#include <set>
#include <memory>
#include <stdexcept>
using namespace std;

// Custom exceptions for the realistic failure modes.
class VotingNotAllowedException : public runtime_error {
public: VotingNotAllowedException(const string& msg) : runtime_error(msg) {}
};
class UnauthorizedAcceptException : public runtime_error {
public: UnauthorizedAcceptException(const string& msg) : runtime_error(msg) {}
};
class InvalidPostException : public runtime_error {
public: InvalidPostException(const string& msg) : runtime_error(msg) {}
};

// The core orchestrator tying every piece together.
class QAService {
    map<string, User> users;                        // userId -> User
    map<string, Question> questions;                // questionId -> Question
    map<string, Answer> answers;                     // answerId -> Answer
    set<string> voteKeys;                              // voterId plus postId, for duplicate checks
    shared_ptr<ReputationStrategy> reputationStrategy;  // pluggable point scheme
    vector<shared_ptr<QAObserver>> observers;            // listeners

    string authorOf(string postId) {
        if (questions.count(postId)) return questions.at(postId).authorId; // question author
        return answers.at(postId).authorId;                                  // answer author
    }

    string typeOf(string postId) {
        return questions.count(postId) ? "QUESTION" : "ANSWER"; // distinguish post type
    }

public:
    QAService(shared_ptr<ReputationStrategy> strategy) : reputationStrategy(strategy) {}

    void addUser(User user) { users.insert({user.userId, user}); }               // register a user
    void addQuestion(Question question) { questions.insert({question.questionId, question}); } // register a question
    void addAnswer(Answer answer) { answers.insert({answer.answerId, answer}); }   // register an answer
    void addObserver(shared_ptr<QAObserver> observer) { observers.push_back(observer); } // register a listener

    void castVote(string voterId, string postId, VoteType voteType) {
        string authorId = authorOf(postId); // who owns this post
        if (authorId == voterId) {             // self-vote check
            for (auto& obs : observers) obs->onVoteRejected(voterId, postId, "Cannot vote on your own post"); // notify
            throw VotingNotAllowedException("Cannot vote on your own post");
        }
        string voteKey = voterId + "|" + postId; // unique key for this voter and post
        if (voteKeys.count(voteKey)) {              // duplicate-vote check
            for (auto& obs : observers) obs->onVoteRejected(voterId, postId, "Already voted on this post"); // notify
            throw VotingNotAllowedException("Already voted on this post");
        }
        User& voter = users.at(voterId); // look up voter
        if (voteType == VoteType::DOWNVOTE && voter.reputation < reputationStrategy->minimumReputationToDownvote()) {
            for (auto& obs : observers) obs->onVoteRejected(voterId, postId, "Insufficient reputation to downvote"); // notify
            throw VotingNotAllowedException("Insufficient reputation to downvote");
        }
        string postType = typeOf(postId); // question or answer
        int authorPoints = reputationStrategy->pointsForVote(postType, voteType); // points for the author
        users.at(authorId).addReputation(authorPoints); // apply to author
        if (voteType == VoteType::DOWNVOTE) { // downvote costs the voter too
            voter.addReputation(reputationStrategy->downvoteVoterCost());
        }
        int scoreDelta = (voteType == VoteType::UPVOTE) ? 1 : -1; // score always moves by 1
        if (questions.count(postId)) questions.at(postId).adjustScore(scoreDelta); // adjust question score
        else answers.at(postId).adjustScore(scoreDelta);                            // adjust answer score
        voteKeys.insert(voteKey); // record this vote
        for (auto& obs : observers) obs->onVoteCast(postId, voterId, voteType); // notify
    }

    void acceptAnswer(string callerId, string questionId, string answerId) {
        auto qit = questions.find(questionId); // look up question
        if (qit == questions.end()) throw InvalidPostException("Unknown question: " + questionId);
        if (qit->second.authorId != callerId) { // must be the question's own author
            throw UnauthorizedAcceptException("Only the question author can accept an answer");
        }
        auto ait = answers.find(answerId); // look up answer
        if (ait == answers.end()) throw InvalidPostException("Unknown answer: " + answerId);
        ait->second.isAccepted = true;                     // mark accepted
        qit->second.acceptedAnswerId = answerId;             // record on the question
        users.at(ait->second.authorId).addReputation(reputationStrategy->pointsForAcceptedAnswerAuthor()); // answerer bonus
        users.at(callerId).addReputation(reputationStrategy->pointsForAcceptingAsker());                      // asker bonus
        for (auto& obs : observers) obs->onAnswerAccepted(answerId, questionId); // notify
    }
};

