import java.util.*;

public class Main {
    public static void main(String[] args) {
        QAService service = new QAService(new StandardReputationStrategy());
        service.addObserver(new ConsoleQAObserver());
        PostIdFactory factory = new PostIdFactory();

        service.addUser(new User("Alice", "Alice", 1));
        service.addUser(new User("Bob", "Bob", 1));
        service.addUser(new User("Carol", "Carol", 200));

        Question q1 = new Question(factory.nextQuestionId(), "Alice", "How do I reverse a linked list?");
        service.addQuestion(q1);

        Answer a1 = new Answer(factory.nextAnswerId(), q1.getQuestionId(), "Bob");
        service.addAnswer(a1);

        Answer a2 = new Answer(factory.nextAnswerId(), q1.getQuestionId(), "Alice");
        service.addAnswer(a2);

        service.castVote("Carol", q1.getQuestionId(), VoteType.UPVOTE);
        service.castVote("Carol", a1.getAnswerId(), VoteType.UPVOTE);

        try {
            service.castVote("Bob", a2.getAnswerId(), VoteType.DOWNVOTE);
        } catch (VotingNotAllowedException e) {
            System.out.println("Caught expected: " + e.getMessage());
        }

