    private final Map<String, Answer> answers = new HashMap<>();
    private final Set<String> voteKeys = new HashSet<>();
    private final ReputationStrategy reputationStrategy;
    private final List<QAObserver> observers = new ArrayList<>();

    public QAService(ReputationStrategy reputationStrategy) {
        this.reputationStrategy = reputationStrategy;
    }

    public void addUser(User user) { users.put(user.getUserId(), user); }
    public void addQuestion(Question question) { questions.put(question.getQuestionId(), question); }
    public void addAnswer(Answer answer) { answers.put(answer.getAnswerId(), answer); }
    public void addObserver(QAObserver observer) { observers.add(observer); }

