        if (questions.containsKey(postId)) return questions.get(postId).getAuthorId();
        return answers.get(postId).getAuthorId();
    }

    private String typeOf(String postId) {
        return questions.containsKey(postId) ? "QUESTION" : "ANSWER";
    }

    public synchronized void castVote(String voterId, String postId, VoteType voteType) {
        String authorId = authorOf(postId);
        if (authorId.equals(voterId)) {
            for (QAObserver obs : observers) obs.onVoteRejected(voterId, postId, "Cannot vote on your own post");
            throw new VotingNotAllowedException("Cannot vote on your own post");
        }
        String voteKey = voterId + "|" + postId;
        if (voteKeys.contains(voteKey)) {
            for (QAObserver obs : observers) obs.onVoteRejected(voterId, postId, "Already voted on this post");
            throw new VotingNotAllowedException("Already voted on this post");
        }
        User voter = users.get(voterId);
        if (voteType == VoteType.DOWNVOTE && voter.getReputation() < reputationStrategy.minimumReputationToDownvote()) {
            for (QAObserver obs : observers) obs.onVoteRejected(voterId, postId, "Insufficient reputation to downvote");
            throw new VotingNotAllowedException("Insufficient reputation to downvote");
        }
        String postType = typeOf(postId);
        int authorPoints = reputationStrategy.pointsForVote(postType, voteType);
        users.get(authorId).addReputation(authorPoints);
        if (voteType == VoteType.DOWNVOTE) {
            voter.addReputation(reputationStrategy.downvoteVoterCost());
        }
        int scoreDelta = voteType == VoteType.UPVOTE ? 1 : -1;
        if (questions.containsKey(postId)) questions.get(postId).adjustScore(scoreDelta);
        else answers.get(postId).adjustScore(scoreDelta);
        voteKeys.add(voteKey);
        for (QAObserver obs : observers) obs.onVoteCast(postId, voterId, voteType);
    }

    public synchronized void acceptAnswer(String callerId, String questionId, String answerId) {
        Question question = questions.get(questionId);
        if (question == null) throw new InvalidPostException("Unknown question: " + questionId);
        if (!question.getAuthorId().equals(callerId)) {
            throw new UnauthorizedAcceptException("Only the question author can accept an answer");
        }
        Answer answer = answers.get(answerId);
        if (answer == null) throw new InvalidPostException("Unknown answer: " + answerId);
        answer.setAccepted(true);
        question.setAcceptedAnswerId(answerId);
        users.get(answer.getAuthorId()).addReputation(reputationStrategy.pointsForAcceptedAnswerAuthor());
        users.get(callerId).addReputation(reputationStrategy.pointsForAcceptingAsker());
        for (QAObserver obs : observers) obs.onAnswerAccepted(answerId, questionId);
    }
}

